from datetime import datetime, timezone, timedelta

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: int, the number of nanoseconds since the Unix epoch
    :param tz: str or None, the timezone to use for local time
    :return: datetime
    """
    if tz is None:
        return datetime.fromtimestamp(nanoseconds / 1e9)
    else:
        timezone_obj = timezone(timedelta(hours=int(tz.split(':')[0]), minutes=int(tz.split(':')[1])))
        return datetime.fromtimestamp(nanoseconds / 1e9, tz=timezone_obj)
