def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding halfway cases to the nearest even number.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 1 == 0:
        return int(n)
    else:
        lower = int(n)
        upper = lower + 1
        if abs(n - lower) < abs(upper - n):
            return lower
        elif abs(n - lower) > abs(upper - n):
            return upper
        else:
            return upper if upper % 2 == 0 else lower
