def round_half_to_even(n):
    """
    Round half to even.

    :param n:
    :return:
    """
    if n % 1 == 0:
        return int(n)
    elif (n - int(n)) == 0.5:
        return int(n) + (1 if int(n) % 2 != 0 else 0)
    else:
        return round(n)

