def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    if not name.isidentifier():
        raise TypeError(f'Invalid class name: {name!r}')

    for field in fields:
        if not isinstance(field, str) or not field.isidentifier():
            raise TypeError(f'Invalid field name: {field!r}')

    namespace = {
        '__annotations__': {field: str for field in fields},
        '__slots__': tuple(fields),
        '__init__': None,
        '_srid': property(lambda self: srid_map.get(self.srid_key))
    }

    for field in fields:
        namespace[f'_{field}_setter'] = (lambda f, fn: lambda self, value: setattr(self, f, value))(f'_{field}', field)

    cls = type(name, (Point,), namespace)

    def __init__(self, *args, **kwargs):
        values = list(args)
        for f, v in kwargs.items():
            values.append(v)
        if len(values) != len(fields):
            raise TypeError(f'{name} expected {len(fields)} arguments')

        for f, v in zip(fields, values):
            setattr(self, f, v)

    cls.__init__ = __init__

    return cls
