            return f"POINT ({' '.join(map(str, self._geometry))})"

        def srid(self):
            return self._srid

        def set_srid(self, srid):
            self._srid = srid

    field_names = [field[0] for field in fields if field[0] is not None]
    field_types = [field[1] for field in fields if field[0] is not None]

    for field_name, field_type in zip(field_names, field_types):
        setattr(PointBase, field_name, field_type)

    for srid, wkt in srid_map.items():
        class_name = f"SRID{srid}"
        class_type = type(class_name, (PointBase,), {})
        setattr(PointBase, class_type.__name__, class_type)

    class Point<PointBase>:
        def __init__(self, *args, srid=None, **kwargs):
            super().__init__(*args, srid=srid, **kwargs)

        def __getitem__(self, key):
            return getattr(self, key)

        def __setitem__(self, key, value):
            setattr(self, key, value)

    Point.__name__ = name
    return Point
