        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = func, args, tuple(kwargs.items()) if typed else args
            try:
                value = cache[key]
                if cache.access_times[key] < timer() - ttl:
                    raise KeyError(key)
                return value
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = value
                return value

        return wrapper

    return decorator

