def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize is None:
        def decorator(func):
            return func
    elif not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer or None")

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.frequencies = {}
            self.current_min_freq = 1

        def get(self, key):
            if key not in self.cache:
                return None

            freq = self.frequencies[key]
            item = self.cache[key]
            del self.cache[key]
            del self.frequencies[key][freq]

            if freq == self.current_min_freq and not self.frequencies[freq]:
                self.current_min_freq += 1

            if freq + 1 in self.frequencies:
                self.frequencies[freq + 1][key] = item
            else:
                self.frequencies[freq + 1] = {key: item}

            self.frequencies[freq + 1][key] = item
            return item

        def put(self, key, value):
            if key in self.cache:
                self.cache[key].value = value
                self.get(key)
                return

            if len(self.cache) >= self.maxsize:
                lfu_key = next(iter(self.frequencies[self.current_min_freq]))
                del self.cache[lfu_key]
                del self.frequencies[self.current_min_freq][lfu_key]
                if not self.frequencies[self.current_min_freq]:
                    del self.frequencies[self.current_min_freq]

            self.cache[key] = value
            self.frequencies[1][key] = value
            self.current_min_freq = 1

        def __getitem__(self, key):
            return self.get(key)

        def __setitem__(self, key, value):
            self.put(key, value)

    def decorator(func):
        memoizer = LFUCache(maxsize, typed)

        @unwrap
        def wrapper(*args, **kwargs):
            key = (func, args if not typed else tuple(type(a) for a in args), tuple(kwargs.items()))
            result = memoizer[key]
            if result is None:
                result = func(*args, **kwargs)
                memoizer[key] = result
            return result

        @classmethod
        def clear(cls):
            memoizer.cache.clear()
            memoizer.frequencies.clear()
            memoizer.current_min_freq = 1

        wrapper.clear = clear

        return wrapper

    return decorator

