def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    base_graph = {}
    for cls in classes:
        base_graph[cls] = set(cls.__bases__)

    def can_remove(cls):
        return all(force_removal(c) for c in base_graph[cls])

    def force_removal(cls):
        return len(base_graph[cls]) == 1 and all(not can_remove(c) for c in cls.__bases__)

    reduced_classes = []
    while classes:
        removable = [cls for cls in classes if can_remove(cls)]
        for cls in removable:
            classes.remove(cls)
            reduced_classes.append(cls)
            for suc in base_graph:
                base_graph[suc].discard(cls)

    reduced_classes.reverse()
    return reduced_classes

