def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        common_base = cls
        for other in classes:
            if other is not cls and issubclass(common_base, other):
                common_base = other
        if common_base not in minimal:
            minimal.append(common_base)
    minimal.sort(key=classes.index)
