    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    try:
        if not hasattr(context, 'value'):
            context.value = {}

        if not hasattr(context, 'error'):
            context.error = {}

        fields = self.fields()
        errors = []

        for field in fields:
            if 'error_E_low' in field:
                try:
                    index = fields.index('E')
                    error_field = 'E_low'
                    if 'x' not in context.error:
                        context.error['x'] = {}
                    context.error['x'][error_field] = {'index': index}
                except ValueError:
                    errors.append('E_low error index not found')

        context.value.update(self.get_value())
        if errors:
            context.error.update({'error': {}})
            for error in errors:
                context.error['error'][error] = True
    except Exception as e:
        context.error.update({'error': {}})
        context.error['error']['exception'] = str(e)
