def difference(d1, d2, level=-1, current_level=0):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    result = {}
    if isinstance(d1, dict) and isinstance(d2, dict):
        if level != current_level:
            current_level += 1
        for key in d1:
            if key not in d2:
                result[key] = d1[key]
            elif level > current_level and isinstance(d1[key], dict) and isinstance(d2[key], dict):
                diff_dict = difference(d1[key], d2[key], level, current_level)
                if diff_dict:
                    result[key] = diff_dict
    return result

def difference(d1, d2, level=-1, current_level=0):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Input must be dictionaries")

    result = {}

    for key in d1:
        if current_level == level:
            result[key] = d1[key]
        elif key in d2:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                sub_diff = difference(d1[key], d2[key], level, current_level + 1)
                if sub_diff:
                    result[key] = sub_diff
            elif d1[key] != d2[key]:
                result[key] = d1[key]
        else:
            result[key] = d1[key]

    return result

