    if self._edges is None or self._values is None:
        raise ValueError("Histogram must be initialized with edges and values")

    if self._is_1d:
        if coord < self._edges[0] or coord > self._edges[-1]:
            return  # ignore out-of-bounds coordinates
        bin_index = np.searchsorted(self._edges, coord, side='right') - 1
        self._values[bin_index] += weight
