    import collections

    errors = []
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')

    def validate_item(item, regex):
        if isinstance(item, list):
            for i, subitem in enumerate(item):
                if not regex.match(subitem):
                    errors.append({f"{item}": f"expected string or bytes-like object"})
        elif not regex.match(item):
            errors.append({f"{item}": f"expected string or bytes-like object"})

    for key, value in labels.items():
        try:
            if not key_regex.match(str(key)):
                errors.append({f"{key}": f"Label key '{key}' does not match the regex {key_regex.pattern}"})
            validate_item(value, value_regex)
        except Exception as e:
            errors.append({f"{key}": f"expected string or bytes-like object, got {type(value).__name__}"})

    if errors:
        raise ValidationError({"errors": errors})

