def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    from krake.data.kubernetes import CustomObserverSchema, KubernetesResourceSchema

    default_schemas = {}

    for resource in app.spec.manifest:
        resource_name = type(resource).__name__

        if resource_name not in default_schemas:
            default_schema = KubernetesResourceSchema()
            default_schema.resource_type = resource_name
            default_schemas[resource_name] = default_schema

        if resource_name not in app.spec.custom_observer_schemas:
            app.spec.custom_observer_schemas[resource_name] = CustomObserverSchema(
                resource=resource_name, observer=default_schemas[resource_name]
            )

    return app.spec.custom_observer_schemas

