    current_species = set(self.species)
    prior_species = set(prior.species)
    if not current_species.issubset(prior_species):
        raise ValueError('Prior inventory must contain all species from the current inventory.')

    # Check if the prior inventory contains all parameters from the current inventory
    current_parameters = set(self.parameters)
    prior_parameters = set(prior.parameters)
    if not current_parameters.issubset(prior_parameters):
        raise ValueError('Prior inventory must contain all parameters from the current inventory.')

    # Check if the prior inventory contains the same number of entries for each species and parameter
    for species in current_species:
        if prior.get_count(species) != self.get_count(species):
            raise ValueError('Prior inventory must contain the same number of entries for each species.')

    for parameter in current_parameters:
        if prior.get_count(parameter) != self.get_count(parameter):
            raise ValueError('Prior inventory must contain the same number of entries for each parameter.')

    # Check if the prior inventory contains valid probability values
    for species in current_species:
        for value in prior.get_values(species):
            if not (0 <= value <= 1):
                raise ValueError('Prior values for species must be in the range [0, 1].')

    for parameter in current_parameters:
        for value in prior.get_values(parameter):
            if not (0 <= value <= 1):
