        if expr.type == 'binary':
            if expr.operation == '&':
                if expr.left.type == 'binary' and expr.left.operation == '|':
                    if expr.left.right == expr:
                        return expr.left.left
                elif expr.right.type == 'binary' and expr.right.operation == '&':
                    if expr.right.left == expr:
                        return expr.right.right
            elif expr.operation == '|':
                if expr.left.type == 'binary' and expr.left.operation == '&':
                    if expr.left.right == expr:
                        return expr.left.left
                elif expr.right.type == 'binary' and expr.right.operation == '|':
                    if expr.right.left == expr:
                        return expr.right.right
        return expr

    def apply_negative_absorption(expr):
        if expr.type == 'binary':
            if expr.operation == '&':
                if expr.right.type == 'binary' and expr.right.operation == '|':
                    if expr.right.left == expr:
                        return expr.right.right
            elif expr.operation == '|':
                if expr.right.type == 'binary' and expr.right.operation == '&':
                    if expr.right.left == expr:
                        return expr.right.right
        return expr

