def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if isinstance(version, str):
            version_parts = version.split('.')
            version_parts = [int(part) for part in version_parts]
        else:
            version_parts = version

        # Increment the last part of the version
        version_parts[-1] += 1

        # Update parts after the last part to zero if necessary
        for i in range(len(version_parts) - 2, -1, -1):
            if version_parts[i] > 9:
                version_parts[i] = 0
                version_parts[i + 1] += 1
            else:
                break

        # Convert parts back to string
        return '.'.join(str(part) for part in version_parts)
    except (ValueError, IndexError):
        return "Invalid version format"

