def validate_version_inventories(self, version_dirs):
    """Validate that each version directory contains an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError("version_dirs must not be empty")

    root_inventory = self.get_inventory('1')  # Assuming the root inventory is always for version 1
    recorded_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        if not os.path.exists(inventory_path):
            raise ValueError(f"No inventory found at {inventory_path}")

        try:
            version_inventory = self.load_inventory(inventory_path)
        except Exception as e:
            raise ValueError(f"Failed to load inventory from {inventory_path}: {e}")

        for content, digest in version_inventory.items():
            if content not in root_inventory or root_inventory[content] != digest:
                recorded_digests[content] = digest

    return recorded_digests
