def _deep_merge_mapping_nodes(lhs_node, rhs_node):
    for key, value in rhs_node.value:
        if key.value not in dict(lhs_node.value):
            lhs_node.value.append((key, value))
        else:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                if not isinstance(dict(lhs_node.value)[key.value], ruamel.yaml.nodes.MappingNode):
                    dict(lhs_node.value)[key.value] = ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=[(key, value)])
                else:
                    idx = [i for i, (k, v) in enumerate(lhs_node.value) if k.value == key.value][0]
                    lhs_node.value[idx] = _deep_merge_mapping_nodes(dict(lhs_node.value)[key.value], value)
    return lhs_node
