def _deep_merge(lhs, rhs):
    for key, rhs_value in rhs.value:
        if key in lhs.value:
            lhs_value = lhs.value[key]
            if isinstance(lhs_value, ruamel.yaml.nodes.MappingNode) and isinstance(rhs_value, ruamel.yaml.nodes.MappingNode):
                lhs.value[key] = _deep_merge(lhs_value, rhs_value)
        else:
            lhs.value[key] = rhs_value.copy()
    return lhs

