def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    from collections import defaultdict

    class ArgumentParser(argparse.ArgumentParser):
        def __init__(self, **kwargs):
            super().__init__(**kwargs)
            self._actions = defaultdict(list)

        def add_argument(self, *args, **kwargs):
            action = super().add_argument(*args, **kwargs)
            self._actions[args[0]].append(action)
            return action

    parser = ArgumentParser(description='Parse command-line arguments')
    subparsers = parser.add_subparsers(dest='subparser_name')

    def add_subparser(subparser_name):
        return subparsers.add_parser(subparser_name)

    def parse_args(args=None):
        namespace = parser.parse_args(args)
        return {namespace.subparser_name if namespace.subparser_name else 'global': namespace}

    return parse_args, parser, add_subparser
