def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    from borgmatic.cli import parser
    import click

    main_command = parser.get_parser('borgmatic')
    bash_completion_script = []

    def add_completion_script(command, prefix=''):
        for arg in command.args:
            if hasattr(arg, 'option_strings'):
                for option_string in arg.option_strings:
                    bash_completion_script.append(f'{prefix}{option_string}')
            if arg.choices:
                bash_completion_script.append(f'{prefix}{option_string} {", ".join(arg.choices)}')

        for subcommand in command.commands.values():
            add_completion_script(subcommand, prefix=f'{prefix}{command.name} ')

    add_completion_script(main_command)

    return '\n'.join(bash_completion_script)
