def human_to_bytes(size_str):
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most cases rounded.

    Args:
        size_str: A string representing a human readable file size (eg: '500K')

    Returns:
        An integer representation of file size in bytes

        Examples::

            >>> human_to_bytes("500")
            500
            >>> human_to_bytes("1K")
            1024
    """
    size_str = size_str.strip().upper()
    if size_str.endswith('B'):
        return int(size_str[:-1])
    elif size_str.endswith('KB'):
        return int(size_str[:-2]) * 1024
    elif size_str.endswith('MB'):
        return int(size_str[:-2]) * 1024 * 1024
    elif size_str.endswith('GB'):
        return int(size_str[:-2]) * 1024 * 1024 * 1024
    elif size_str.endswith('TB'):
        return int(size_str[:-2]) * 1024 * 1024 * 1024 * 1024
    else:
        raise ValueError("Invalid size format: {}".format(size_str))

