        raise ValueError("The alphabet must not be empty")
    if not (1 <= len(alphabet) <= 36):
        raise ValueError("The length of the alphabet must be between 1 and 36")
    if number < 0:
        raise ValueError("The number must be non-negative")

    if number == 0:
        if padding is None:
            padding = 1
        return alphabet[0] * padding

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    result = ''.join(reversed(digits))

    if padding is not None and padding > len(result):
        result = alphabet[0] * (padding - len(result)) + result

    return result
