def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    if not all(isinstance(c, str) and len(c) == 1 for c in alphabet):
        raise ValueError("alphabet must only contain single characters")
    if padding is not None and padding <= 0:
        raise ValueError("padding must be a positive integer or None")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding or 1)

    digits = []
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    result = ''.join(reversed(digits))

    if padding is not None:
        result = result.zfill(padding)

    return result

