def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    from pathlib import Path
    tmp_path = Path(tmp_path)
    if not archive_path.exists():
        raise ValueError(f"Archive path '{archive_path}' does not exist.")

    if not filename:
        filename = archive_path.name

    extract_path = tmp_path / filename
    extract_path.mkdir(parents=True, exist_ok=True)

    try:
        if archive_path.suffix == '.tar.gz':
            subprocess.run(['tar', '-xzf', archive_path, '-C', extract_path], check=True)
        elif archive_path.suffix == '.tar.bz2':
            subprocess.run(['tar', '-xjf', archive_path, '-C', extract_path], check=True)
        elif archive_path.suffix == '.zip':
            subprocess.run(['unzip', archive_path, '-d', extract_path], check=True)
        else:
            raise ValueError(f"Unsupported archive type: {archive_path.suffix}")
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to extract archive: {e}")

    repo_url = f"file://{extract_path}"
    return repo_url

