import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    if not isinstance(commands, list):
        raise ValueError("commands must be a list")

    if not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings")

    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary")

    try:
        for command in commands:
            command_with_args = [command] + args

            if verbose:
                print(f"Running command: {' '.join(command_with_args)}")

            output = subprocess.check_output(command_with_args, cwd=cwd, stderr=subprocess.STDOUT,
                                             shell=False, env=env)

            if hide_stderr:
                output = output.decode().splitlines()
                output = [line for line in output if 'error' not in line.lower()]
                output = '\n'.join(output)

            if verbose:
                print(f"Command output: {output}")

            return output

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with output: {e.output.decode()}")

        raise RuntimeError(f"Failed to run command: {' '.join(commands)}")
