def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    children = {s for s, p, o in graph.triples((None, prop, None))}
    parents = {o for s, p, o in graph.triples((None, prop, None))}

    for parent in parents:
        children.discard(parent)

    return children | roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()

    # Identify nodes that have no parents in the given property
    candidate_roots = set(graph.subjects(prop))

    # For each candidate root, check if it is a descendant of any other node
    for potential_root in candidate_roots:
        for node in graph.subjects(prop):
            if node == potential_root:
                continue
            path = set()
            current_node = potential_root
            while current_node in graph.objects(node, prop):
                current_node = graph.objects(node, prop).next()
                if current_node in path:
                    break  # Cycle detected
                path.add(current_node)
            else:
                # If we exit the loop without finding a cycle, it means the potential_root is not a descendant
                roots.add(potential_root)

    return roots

