def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    import toml
    from logging import LogRecord

    parsed_configs = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.isfile(filename):
            log_records.append(LogRecord('load_configurations', logging.ERROR, filename, 0, f"File '{filename}' not found.", None, None))
            continue

        try:
            with open(filename, 'r') as file:
                content = file.read()
                if filename.endswith('.json'):
                    config = json.loads(content)
                elif filename.endswith('.toml'):
                    config = toml.loads(content)
                else:
                    log_records.append(LogRecord('load_configurations', logging.ERROR, filename, 0, f"Unsupported file format for '{filename}'.", None, None))
                    continue

                if resolve_env:
                    config = os.path.expandvars(config)

                if overrides:
                    config = {**config, **overrides}

                parsed_configs[filename] = config
        except Exception as e:
            log_records.append(LogRecord('load_configurations', logging.ERROR, filename, 0, f"Error parsing '{filename}': {str(e)}", None, None))

    return parsed_configs, log_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import toml
    import yaml
    import os
    import glob

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if isinstance(filename, str):
            filenames = [filename]
        else:
            filenames = glob.glob(filename)

        for fn in filenames:
            try:
                if fn.endswith('.toml'):
                    with open(fn) as fd:
                        config = toml.loads(fd.read())
                elif fn.endswith('.yaml') or fn.endswith('.yml'):
                    with open(fn) as fd:
                        config = yaml.safe_load(fd.read())
                else:
                    log_records.append(logging.LogRecord('load_configurations', logging.ERROR, fn, 0, 'Unsupported file type: %s', None, None))
                    continue

                if resolve_env:
                    config = os.path.expandvars(config)

                if overrides:
                    config = {**config, **overrides}

                config_dict[fn] = config
            except FileNotFoundError:
                log_records.append(logging.LogRecord('load_configurations', logging.ERROR, fn, 0, 'File not found: %s', None, None))
            except (toml.TomlDecodeError, yaml.YAMLError) as e:
                log_records.append(logging.LogRecord('load_configurations', logging.ERROR, fn, 0, 'Error parsing %s: %s', (fn, str(e)), None))

    return config_dict, log_records

