def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        return (None, None)

    seq_type = type(seq)
    if is_sequence(seq):
        return (seq, seq_type)

    # If seq is not a sequence, convert it to a list
    try:
        seq = list(seq)
        return (seq, list)
    except Exception as e:
        raise Exception(f"Error: Unable to convert input to a sequence. {str(e)}")

def is_sequence(value):
    """Determine if a value is a sequence type.

    Returns:
      ``True`` if `value` is a sequence type (e.g., ``list``, or ``tuple``).
      String types will return ``False``.

    NOTE: On Python 3, strings have the __iter__ defined, so a simple hasattr
    check is insufficient.
    """
    return (hasattr(value, "__iter__") and not
            isinstance(value, (str, bytes)))
