from dateutil import tz
from datetime import datetime

def isoparse(dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    :param dt_str: A string containing only an ISO-8601 datetime string.
    :return: A :class:`datetime.datetime` representing the string.
    """
    try:
        if dt_str.endswith('Z'):
            return datetime.strptime(dt_str, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=tz.tzutc())
        elif 'T' in dt_str:
            dt_str = dt_str.replace(',', '.')
            if '.' in dt_str:
                return datetime.strptime(dt_str, '%Y-%m-%dT%H:%M:%S.%f').replace(tzinfo=tz.tzutc())
            else:
                return datetime.strptime(dt_str, '%Y-%m-%dT%H:%M:%S').replace(tzinfo=tz.tzutc())
        else:
            return datetime.strptime(dt_str, '%Y-%m-%d')
    except ValueError as e:
        raise ValueError(f"Failed to parse datetime string: {dt_str}") from e
