    # Check if the tag is non-empty
    if not tag:
        return False

    # Check if the tag contains only alphanumeric characters and underscores
    if not tag.replace('_', '').isalnum():
        return False

    # Check if the tag starts with an alphanumeric character
    if not tag[0].isalnum():
        return False

    # Check if the tag ends with an alphanumeric character
    if not tag[-1].isalnum():
        return False

    # If all checks pass, the tag is valid
    return True

