def parse_diaspora_webfinger(document):
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        try:
            xmldoc = ET.fromstring(document)
            subject = xmldoc.find("{http://purl.org/opensearch/extensions/}totalItems").text
            return {
                "subject": subject,
                "links": [
                    {
                        "href": link.get("{http://www.w3.org/1999/xhtml}href"),
                        "rel": link.get("rel"),
                    }
                    for link in xmldoc.findall(".//link")
                ],
            }
        except ET.ParseError:
            logger.error("Failed to parse Diaspora webfinger document")
            return None

