import json
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        pass

    xrd_namespaces = {
        "DIASPORA": "http://diaspora.org/ns/2010/04/ns#",
        "XRD": "http://docs.oasis-open.org/ns/xri/xrd-1.0",
    }
    xrd = None
    try:
        from defusedxml.ElementTree import fromstring
        xrd = fromstring(document)
    except ImportError as e:
        logger.error("parse_diaspora_webfinger: defusedxml is not installed: %s", e)
    except Exception as e:
        logger.error("parse_diaspora_webfinger: error parsing XRD: %s", e)

    if xrd is not None:
        for link in xrd.findall(".//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link"):
            rel = link.get("rel")
            if rel == "alternate" and link.get("type") == "text/html":
                return {"hcard_url": link.get("href")}
            elif rel == "http://diaspora.org/ns/2010/04/ns#profile_alias":
                return {"alias": link.get("template").format(uri="{uri}")}

    return {}
