def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
    except ValueError:
        # Document is in XRD format
        xrd = ElementTree.fromstring(document)
        hcard_url = xrd.find("{http://webfinger.net/rel/profile}link", {"rel": "http://microformats.org/format/hcard"}).attrib["href"]
        return {"hcard_url": hcard_url}
    # Document is in JSON format
    return {key: value for key, value in data.items()}

