def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        if not settings_dirs or not isinstance(settings_dirs, list):
            raise ValueError("settings_dirs must be a non-empty list")

        file_names = []
        for directory in settings_dirs:
            try:
                files = sorted([
                    os.path.join(directory, fname)
                    for fname in os.listdir(directory)
                    if (fname.endswith('.py') or fname.endswith('.ini')) and fname != spec_option
                ])
                file_names.extend(files)
            except OSError:
                continue

        return file_names
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

