def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Args:
        settings_dirs (list of str): List of directories to search for files
        spec_option (str): Specification option to filter files

    Returns:
        list of str: List of matching file names
    """
    try:
        matching_files = []
        for directory in settings_dirs:
            for root, _, files in os.walk(directory):
                for file in files:
                    if file.endswith(spec_option):
                        matching_files.append(os.path.join(root, file))
        return sorted(matching_files)
    except Exception as e:
        print(f"An error occurred: {e}")
        return []

