        # Check if the argument has a default value in the spec
        if arg.name in self.spec:
            defaults[arg.name] = self.spec[arg.name]

        # Check if the argument has a default value specified in the default_spec
        if arg.name in self.default_spec:
            defaults[arg.name] = self.default_spec[arg.name]

        # Check if the argument has a default value specified in the instance attributes
        if hasattr(self, arg.name):
            defaults[arg.name] = getattr(self, arg.name)

        # Check if the argument has a default value specified in a configuration file
        if arg.name in self.config:
            defaults[arg.name] = self.config[arg.name]

        # Check if the argument has a default value specified in environment variables
        if arg.name in os.environ:
            defaults[arg.name] = os.environ[arg.name]

    return defaults
