    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    flatten_dict = {}
    spec_path = os.path.join(plugin_dir, 'spec.json')

    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at {spec_path}")

    with open(spec_path, 'r') as file:
        spec_data = json.load(file)

    def flatten_dict_helper(data, parent_key='', sep='_'):
        for k, v in data.items():
            if isinstance(v, dict):
                flatten_dict_helper(v, parent_key + sep + k if parent_key else k)
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    flatten_dict_helper(item, parent_key + sep + k + str(i))
            else:
                flatten_dict[parent_key + sep + k if parent_key else k] = v

    flatten_dict_helper(spec_data)
    return flatten_dict
