    Adds the spec cli options to to the main entry point.

    :param root_subparsers: the subparser object to extend.
    """
    if not hasattr(self, 'cli_options'):
        raise ValueError("CLI options not set. Please initialize with cli_options.")

    for option in self.cli_options:
        try:
            subparser = root_subparsers.add_parser(option['name'], description=option['description'])
            for action in option['actions']:
                subparser.add_argument(*action['args'], **action['kwargs'])
        except Exception as e:
            raise ValueError(f"Failed to extend CLI: {e}")
